css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .escena-caja{border: 1.5px solid var(--bosque); border-radius: 10px; padding: 4px 8px;}
.mz .escena-caja svg{width: 100%; max-width: 420px; height: auto; display: block; margin: 0 auto;}
.mz .caminos-resp{display: flex; gap: 16px; margin-top: 4px;}
.mz .camino-item{display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; flex: 1;}
.mz .camino-item .linea-resp{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 16px;}
.mz .rodea-fila{display: flex; align-items: center; gap: 6px; font-size: 13.5px; font-weight: 600; margin-bottom: 6px; flex-wrap: wrap;}
.mz .opcion-circ{display: inline-flex; width: 25px; height: 25px; border: 1.8px solid var(--bosque); border-radius: 50%; align-items: center; justify-content: center; font-family: sans-serif; font-weight: 700; font-size: 13px;}
.mz .linea-inline{display: inline-block; width: 130px; border-bottom: 1.5px solid var(--bosque); height: 15px; vertical-align: bottom;}
.mz .objetos-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 40px; align-items: center;}
.mz .objetos-col{display: flex; flex-direction: column; gap: 4px; align-items: center;}
.mz .objeto-caja{display: flex; align-items: center; justify-content: center; min-height: 38px;}
.mz .objeto-caja svg{width: 40px; height: 40px;}
.mz .objetos-nom{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 8px; text-align: center; font-size: 13.5px; font-weight: 700; width: 100%;}
.mz .puntos-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 16px;}
.mz .puntos-caja{border: 1.5px solid var(--bosque); border-radius: 10px; padding: 6px 8px; display: flex; flex-direction: column; align-items: center; gap: 2px;}
.mz .puntos-caja svg{width: 150px; height: 110px;}
.mz .puntos-resp{font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 6px; width: 100%;}
.mz .puntos-resp .linea-resp{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 16px;}
.mz .vf-fila{display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 600; margin-bottom: 5px;}
.mz .vf-frase{flex: 1;}
.mz .vf-ops{display: flex; gap: 8px; flex-shrink: 0;}
.mz .vf-circ{width: 22px; height: 22px; border: 1.8px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-weight: 700; font-size: 12px;}
